@Injectable()
export class ServiceOrderIntakePdfService {
  async generate(input: GenerateIntakePdfInput): Promise<GeneratedPdfResult> {
    const directory = join(process.cwd(), 'storage', 'temp', 'service-orders');
    await fs.mkdir(directory, { recursive: true });

    const fileName = `resumen-ordenes-${randomUUID()}.pdf`;
    const absolutePath = join(directory, fileName);
    const fileBuffer = await this.createPdfBuffer((document) => {
      this.renderIntakeDocument(document, input);
      this.drawFooters(document);
    });
    await fs.writeFile(absolutePath, fileBuffer);

    return {
      fileName,
      absolutePath,
      mimeType: 'application/pdf',
    };
  }

  async generateSingleOrderSummaryBuffer(input: GenerateSingleOrderSummaryPdfInput): Promise<Buffer> {
    return this.createPdfBuffer((document) => {
      this.renderSingleOrderSummaryDocument(document, input);
      this.drawFooters(document);
    });
  }

  private async createPdfBuffer(render: (document: PdfDocumentInstance) => void): Promise<Buffer> {
    const document = new PDFDocument({ margin: PAGE_MARGIN, bufferPages: true, autoFirstPage: false });
    const chunks: Buffer[] = [];

    return new Promise<Buffer>((resolve, reject) => {
      document.on('data', (chunk: Buffer | Uint8Array) => {
        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
      });
      document.on('end', () => resolve(Buffer.concat(chunks)));
      document.on('error', reject);

      try {
        render(document);
        document.end();
      } catch (error) {
        reject(error);
      }
    });
  }

  private renderIntakeDocument(document: PdfDocumentInstance, input: GenerateIntakePdfInput): void {
    document.addPage();
    let cursorY = this.drawHeader(document, input.createdAt, 'Recepción de órdenes de servicio');
    cursorY = this.drawClientSummary(document, input, cursorY);

    input.orders.forEach((order, index) => {
      const cardHeight = this.measureOrderCardHeight(document, order);
      if (cursorY + cardHeight > this.getContentBottom(document)) {
        document.addPage();
        cursorY = this.drawHeader(document, input.createdAt, 'Recepción de órdenes de servicio');
      }

      cursorY = this.drawOrderCard(document, order, index, cursorY);
    });

    const termsHeight = this.measureTermsSectionHeight(document);
    cursorY = this.ensureSectionSpace(
      document,
      cursorY,
      termsHeight,
      input.createdAt,
      null,
    );
    this.drawTermsSection(document, cursorY);
  }

  private renderSingleOrderSummaryDocument(
    document: PdfDocumentInstance,
    input: GenerateSingleOrderSummaryPdfInput,
  ): void {
    document.addPage();
    let cursorY = this.drawHeader(document, input.createdAt, 'Resumen de recepción');

    cursorY = this.drawSingleOrderOverview(document, input, cursorY);
    const items = this.resolveSingleOrderItems(input);
    cursorY = this.drawEquipmentTableHeader(document, cursorY, items.length);
    items.forEach((item, index) => {
      const rowHeight = this.measureSingleOrderItemCardHeight(document, item, index);
      if (cursorY + rowHeight + PAGE_BREAK_SAFETY > this.getContentBottom(document)) {
        document.addPage();
        cursorY = this.drawContinuationHeader(document, input.code);
        cursorY = this.drawEquipmentTableHeader(document, cursorY, items.length);
      }
      cursorY = this.drawSingleOrderItemCard(document, item, index, cursorY);
    });

    document.addPage();
    cursorY = this.drawContinuationHeader(document, input.code);
    this.drawTermsSection(document, cursorY);
  }

  private ensureSectionSpace(
    document: PdfDocumentInstance,
    currentY: number,
    requiredHeight: number,
    createdAt: Date,
    title?: string | null,
  ): number {
    if (currentY + requiredHeight + PAGE_BREAK_SAFETY <= this.getContentBottom(document)) {
      return currentY;
    }

    document.addPage();
    return this.drawHeader(document, createdAt, title);
  }

  private drawHeader(document: PdfDocumentInstance, createdAt: Date, title?: string | null): number {
    const headerX = PAGE_MARGIN;
    const headerY = PAGE_MARGIN;
    const headerWidth = this.getContentWidth(document);
    const logoHeight = HEADER_LOGO_WIDTH * LOGO_ASPECT_RATIO;
    const logoY = headerY + 5;

    document.save();
    document.rect(headerX, headerY, 4, 42).fill(ACCENT_COLOR);
    document.restore();

    document.image(Buffer.from(LOGO_BASE64, 'base64'), headerX + 16, logoY, {
      width: HEADER_LOGO_WIDTH,
    });
    document
      .fillColor(LABEL_COLOR)
      .font('Helvetica')
      .fontSize(6.5)
      .text(`RUC ${COMPANY_RUC}`, headerX + 16, headerY + 32, {
        width: 240,
      })
      .text(`${COMPANY_ADDRESS}  |  Ubigeo ${COMPANY_UBIGEO}`, headerX + 16, headerY + 42, {
        width: 240,
      });

    const rightX = headerX + 240;
    const rightWidth = headerWidth - 240;
    document
      .fillColor(LABEL_COLOR)
      .font('Helvetica')
      .fontSize(HEADER_DATE_FONT_SIZE)
      .text(`Emitido el ${this.formatDateTime(createdAt)}`, rightX, headerY + 26, {
        width: rightWidth,
        align: 'right',
      });

    document
      .fillColor(TITLE_COLOR)
      .font('Helvetica-Bold')
      .fontSize(9)
      .text((title || 'Continuación').toUpperCase(), rightX, headerY + 7, {
        width: rightWidth,
        align: 'right',
        characterSpacing: 1.2,
      });

    document.moveTo(headerX, headerY + 55).lineTo(headerX + headerWidth, headerY + 55).strokeColor(LINE_COLOR).lineWidth(0.7).stroke();
    return headerY + 75;
  }

  private drawContinuationHeader(document: PdfDocumentInstance, orderCode: string): number {
    const y = PAGE_MARGIN;
    document.fillColor(ACCENT_COLOR).font('Helvetica-Bold').fontSize(9).text(`MACROCHIPS  |  RUC ${COMPANY_RUC}`, PAGE_MARGIN, y, {
      characterSpacing: 1.2,
    });
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.5).text(orderCode, PAGE_MARGIN, y, {
      width: this.getContentWidth(document),
      align: 'right',
    });
    document.moveTo(PAGE_MARGIN, y + 20).lineTo(document.page.width - PAGE_MARGIN, y + 20).strokeColor(LINE_COLOR).lineWidth(0.7).stroke();
    return y + 42;
  }

  private drawSingleOrderOverview(
    document: PdfDocumentInstance,
    input: GenerateSingleOrderSummaryPdfInput,
    startY: number,
  ): number {
    const width = this.getContentWidth(document);
    document.fillColor(ACCENT_COLOR).font('Helvetica-Bold').fontSize(8).text('ORDEN DE SERVICIO', PAGE_MARGIN, startY, {
      characterSpacing: 1.4,
    });
    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(21).text(input.code, PAGE_MARGIN, startY + 16, { width });
    const bandY = startY + 52;
    const bandHeight = 86;
    document.save();
    document.rect(PAGE_MARGIN, bandY, width, bandHeight).fill(CLIENT_BOX_BACKGROUND);
    document.restore();
    const fields = [
      { label: 'Cliente', value: input.clientName?.trim() || 'Sin cliente' },
      { label: 'Documento', value: input.clientDocument?.trim() || 'No especificado' },
      { label: 'Teléfono', value: input.clientPhone?.trim() || 'No especificado' },
      { label: 'Servicio', value: this.formatServiceType(input.serviceType) },
      { label: 'Recepción', value: this.formatDateTime(input.createdAt) },
      { label: 'Correo', value: input.clientEmail?.trim() || 'No especificado' },
    ];
    const columnWidth = width / 3;
    fields.forEach((field, index) => {
      const column = index % 3;
      const row = Math.floor(index / 3);
      const x = PAGE_MARGIN + column * columnWidth + 14;
      const y = bandY + 13 + row * 38;
      document.fillColor(LABEL_COLOR).font('Helvetica-Bold').fontSize(7).text(field.label.toUpperCase(), x, y, { width: columnWidth - 28, characterSpacing: 0.7 });
      document.fillColor(VALUE_COLOR).font('Helvetica').fontSize(9.5).text(field.value, x, y + 12, { width: columnWidth - 28, ellipsis: true });
    });
    return bandY + bandHeight + 24;
  }

  private drawSingleOrderItemCard(
    document: PdfDocumentInstance,
    item: GenerateSingleOrderSummaryPdfItem,
    index: number,
    startY: number,
  ): number {
    const rowHeight = this.measureSingleOrderItemCardHeight(document, item, index);
    const width = this.getContentWidth(document);
    const numberWidth = 48;
    const contentX = PAGE_MARGIN + numberWidth;
    const contentWidth = width - numberWidth;
    document.moveTo(PAGE_MARGIN, startY).lineTo(PAGE_MARGIN + width, startY).strokeColor(LINE_COLOR).lineWidth(0.7).stroke();
    document.fillColor(HEADER_ACCENT_COLOR).font('Helvetica-Bold').fontSize(20).text(String(index + 1).padStart(2, '0'), PAGE_MARGIN, startY + 15, { width: 34 });
    const equipmentName = [this.formatEquipmentType(item.equipmentType), item.brand?.trim(), item.model?.trim()].filter(Boolean).join(' - ');
    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(12.5).text(equipmentName, contentX, startY + 14, { width: contentWidth });
    const meta = [item.code, `Serie: ${item.serialNumber?.trim() || 'No especificada'}`].join('  |  ');
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.3).text(meta, contentX, startY + 34, { width: contentWidth });
    document.fillColor(ACCENT_COLOR).font('Helvetica-Bold').fontSize(7).text('PROBLEMA REPORTADO', contentX, startY + 54, { width: contentWidth, characterSpacing: 0.8 });
    document.fillColor(VALUE_COLOR).font('Helvetica').fontSize(10).text(item.initialIssue || 'Sin detalle', contentX, startY + 67, { width: contentWidth, lineGap: 1.5 });
    const detailsY = startY + rowHeight - 34;
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.2).text(`Accesorios: ${item.accessories?.trim() || 'Sin accesorios'}`, contentX, detailsY, { width: contentWidth / 2 - 8 });
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.2).text(`Observaciones: ${item.notes?.trim() || 'Sin observaciones'}`, contentX + contentWidth / 2, detailsY, { width: contentWidth / 2 });
    return startY + rowHeight;
  }

  private drawEquipmentTableHeader(document: PdfDocumentInstance, startY: number, count = 0): number {
    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(12).text('Equipos recibidos', PAGE_MARGIN, startY);
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.5).text(`${count} ${count === 1 ? 'equipo' : 'equipos'}`, PAGE_MARGIN, startY + 2, {
      width: this.getContentWidth(document), align: 'right',
    });
    return startY + 27;
  }

  private getEquipmentTableColumns(document: PdfDocumentInstance): Array<{ label: string; width: number }> {
    const width = this.getContentWidth(document);
    return [
      { label: '#', width: 58 },
      { label: 'EQUIPO', width: 128 },
      { label: 'IDENTIFICACIÓN', width: 142 },
      { label: 'DETALLE DE RECEPCIÓN', width: width - 328 },
    ];
  }

  private getEquipmentTableValues(item: GenerateSingleOrderSummaryPdfItem, index: number): string[] {
    const equipment = [
      this.formatEquipmentType(item.equipmentType),
      [item.brand?.trim(), item.model?.trim()].filter(Boolean).join(' ') || 'Marca y modelo no especificados',
    ].join('\n');
    const identification = [item.code, `Serie: ${item.serialNumber?.trim() || 'No especificada'}`].join('\n');
    const details = [
      item.initialIssue,
      `Accesorios: ${item.accessories?.trim() || 'Sin accesorios'}`,
      item.notes?.trim() ? `Observaciones: ${item.notes.trim()}` : null,
    ].filter(Boolean).join('\n');
    return [`${index + 1}\n${this.formatPriority(item.priority)}`, equipment, identification, details];
  }

  private drawTextSectionCard(
    document: PdfDocumentInstance,
    title: string,
    body: string,
    startY: number,
  ): number {
    const cardX = PAGE_MARGIN;
    const cardY = startY;
    const cardWidth = this.getContentWidth(document);
    const innerX = cardX + ORDER_CARD_PADDING;
    const innerWidth = cardWidth - ORDER_CARD_PADDING * 2;
    const bodyHeight = this.measureTextHeight(document, 'Helvetica', 10.5, body || 'Sin detalle', innerWidth);
    const cardHeight = ORDER_CARD_PADDING * 2 + 18 + bodyHeight;

    document.save();
    document.roundedRect(cardX, cardY, cardWidth, cardHeight, 8).fillAndStroke('#FFFFFF', CARD_BORDER);
    document.restore();

    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(13).text(title, innerX, cardY + ORDER_CARD_PADDING, {
      width: innerWidth,
    });
    document.fillColor(VALUE_COLOR).font('Helvetica').fontSize(10.5).text(body || 'Sin detalle', innerX, cardY + ORDER_CARD_PADDING + 20, {
      width: innerWidth,
      align: 'left',
    });

    return cardY + cardHeight + CARD_GAP;
  }

  private drawTermsSection(document: PdfDocumentInstance, startY: number): number {
    const width = this.getContentWidth(document);
    document.fillColor(ACCENT_COLOR).font('Helvetica-Bold').fontSize(8).text('INFORMACIÓN IMPORTANTE', PAGE_MARGIN, startY, { characterSpacing: 1.3 });
    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(19).text('Términos del servicio', PAGE_MARGIN, startY + 17, { width });
    document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(9).text('Condiciones aplicables a la recepción, atención y entrega de los equipos.', PAGE_MARGIN, startY + 43, { width });
    const gap = 28;
    const columnWidth = (width - gap) / 2;
    const columns = [STANDARD_TERMS.slice(0, 3), STANDARD_TERMS.slice(3)];
    let maxY = startY + 78;
    columns.forEach((terms, columnIndex) => {
      const x = PAGE_MARGIN + columnIndex * (columnWidth + gap);
      let y = startY + 78;
      terms.forEach((term) => {
        document.moveTo(x, y).lineTo(x + 22, y).strokeColor(HEADER_ACCENT_COLOR).lineWidth(1.5).stroke();
        document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(9.4).text(term.title, x, y + 10, { width: columnWidth });
        const titleHeight = document.heightOfString(term.title, { width: columnWidth });
        const bodyY = y + 14 + titleHeight;
        document.fillColor(LABEL_COLOR).font('Helvetica').fontSize(8.3).text(term.body, x, bodyY, { width: columnWidth, lineGap: 2 });
        const bodyHeight = document.heightOfString(term.body, { width: columnWidth, lineGap: 2 });
        y = bodyY + bodyHeight + 24;
      });
      maxY = Math.max(maxY, y);
    });
    return maxY;
  }

  private drawClientSummary(document: PdfDocumentInstance, input: GenerateIntakePdfInput, startY: number): number {
    const boxX = PAGE_MARGIN;
    const boxY = startY;
    const boxWidth = this.getContentWidth(document);
    const boxHeight = 62;
    const columnGap = 16;
    const columnWidth = (boxWidth - columnGap * 2 - CLIENT_BOX_PADDING * 2) / 3;
    const contentY =
      boxY
      + Math.max(
        10,
        (boxHeight
          - this.measureSummaryFieldHeight(
            document,
            'Cantidad de órdenes',
            String(input.orders.length),
            columnWidth,
          ))
          / 2,
      );

    document.save();
    document.roundedRect(boxX, boxY, boxWidth, boxHeight, 10).fillAndStroke(CLIENT_BOX_BACKGROUND, CLIENT_BOX_BORDER);
    document.restore();

    this.drawSummaryField(document, boxX + CLIENT_BOX_PADDING, contentY, columnWidth, 'Cliente', input.clientName?.trim() || 'No especificado');
    this.drawSummaryField(document, boxX + CLIENT_BOX_PADDING + columnWidth + columnGap, contentY, columnWidth, 'Fecha', this.formatDateTime(input.createdAt));
    this.drawSummaryField(document, boxX + CLIENT_BOX_PADDING + (columnWidth + columnGap) * 2, contentY, columnWidth, 'Cantidad de órdenes', String(input.orders.length));

    return boxY + boxHeight + SECTION_GAP;
  }

  private drawOrderCard(document: PdfDocumentInstance, order: IntakePdfOrder, index: number, startY: number): number {
    const cardX = PAGE_MARGIN;
    const cardY = startY;
    const cardWidth = this.getContentWidth(document);
    const cardHeight = this.measureOrderCardHeight(document, order);
    const innerX = cardX + ORDER_CARD_ACCENT_WIDTH + ORDER_CARD_PADDING;
    const innerWidth = cardWidth - ORDER_CARD_ACCENT_WIDTH - ORDER_CARD_PADDING * 2;

    document.save();
    document.roundedRect(cardX, cardY, cardWidth, cardHeight, 12).fillAndStroke('#FFFFFF', CARD_BORDER);
    document.rect(cardX, cardY, ORDER_CARD_ACCENT_WIDTH, cardHeight).fill(ACCENT_COLOR);
    document.restore();

    document
      .fillColor(TITLE_COLOR)
      .font('Helvetica-Bold')
      .fontSize(14)
      .text(`Orden ${index + 1}: ${order.code}`, innerX, cardY + ORDER_CARD_PADDING, {
        width: innerWidth,
      });

    const titleHeight = document.heightOfString(`Orden ${index + 1}: ${order.code}`, {
      width: innerWidth,
    });
    const columnsY = cardY + ORDER_CARD_PADDING + titleHeight + 12;
    const columnWidth = (innerWidth - COLUMN_GAP) / 2;
    const leftX = innerX;
    const rightX = innerX + columnWidth + COLUMN_GAP;

    this.drawFieldColumn(document, leftX, columnsY, columnWidth, [
      { label: 'Tipo de servicio', value: this.formatServiceType(order.serviceType) },
      { label: 'Equipo', value: order.equipmentLabel },
      { label: 'Técnico', value: order.technicianName?.trim() || 'Pendiente' },
    ]);

    this.drawFieldColumn(document, rightX, columnsY, columnWidth, [
      { label: 'Falla reportada', value: order.initialIssue },
      { label: 'Entrega estimada', value: this.formatOptionalDateTime(order.estimatedDeliveryDate) || 'No especificada' },
      { label: 'Notas', value: order.notes?.trim() || 'Sin notas' },
    ]);

    return cardY + cardHeight + CARD_GAP;
  }

  private drawFieldCard(
    document: PdfDocumentInstance,
    title: string,
    fields: Array<{ label: string; value: string }>,
    startY: number,
  ): number {
    const cardX = PAGE_MARGIN;
    const cardY = startY;
    const cardWidth = this.getContentWidth(document);
    const cardHeight = this.measureFieldCardHeight(document, fields);
    const innerX = cardX + ORDER_CARD_ACCENT_WIDTH + ORDER_CARD_PADDING;
    const innerWidth = cardWidth - ORDER_CARD_ACCENT_WIDTH - ORDER_CARD_PADDING * 2;

    document.save();
    document.roundedRect(cardX, cardY, cardWidth, cardHeight, 12).fillAndStroke('#FFFFFF', CARD_BORDER);
    document.rect(cardX, cardY, ORDER_CARD_ACCENT_WIDTH, cardHeight).fill(ACCENT_COLOR);
    document.restore();

    document.fillColor(TITLE_COLOR).font('Helvetica-Bold').fontSize(14.5).text(title, innerX, cardY + ORDER_CARD_PADDING, {
      width: innerWidth,
    });

    const titleHeight = document.heightOfString(title, { width: innerWidth });
    document
      .moveTo(innerX, cardY + ORDER_CARD_PADDING + titleHeight + 8)
      .lineTo(cardX + cardWidth - ORDER_CARD_PADDING, cardY + ORDER_CARD_PADDING + titleHeight + 8)
      .strokeColor(CARD_BORDER)
      .lineWidth(0.7)
      .stroke();
    const columnsY = cardY + ORDER_CARD_PADDING + titleHeight + 18;
    const columnWidth = (innerWidth - COLUMN_GAP) / 2;
    const midpoint = Math.ceil(fields.length / 2);

    this.drawFieldColumn(document, innerX, columnsY, columnWidth, fields.slice(0, midpoint));
    this.drawFieldColumn(document, innerX + columnWidth + COLUMN_GAP, columnsY, columnWidth, fields.slice(midpoint));

    return cardY + cardHeight + CARD_GAP;
  }

  private drawFooters(document: PdfDocumentInstance): void {
    const range = document.bufferedPageRange();
    for (let index = range.start; index < range.start + range.count; index += 1) {
      document.switchToPage(index);
      const footerY = document.page.height - PAGE_MARGIN - 24;
      document.save();
      document.moveTo(PAGE_MARGIN, footerY).lineTo(document.page.width - PAGE_MARGIN, footerY).strokeColor(LINE_COLOR).lineWidth(0.7).stroke();
      document
        .fillColor(LABEL_COLOR)
        .font('Helvetica')
        .fontSize(8)
        .text(`CORPORACIÓN MACROCHIPS  ·  Página ${index - range.start + 1} de ${range.count}`, PAGE_MARGIN, footerY + 6, {
          width: this.getContentWidth(document),
          align: 'center',
        });
      document.restore();
    }
  }

  private drawSummaryField(
    document: PdfDocumentInstance,
    x: number,
    y: number,
    width: number,
    label: string,
    value: string,
  ): void {
    document.fillColor(LABEL_COLOR).font('Helvetica-Bold').fontSize(8).text(label.toUpperCase(), x, y, { width });
    document.fillColor(VALUE_COLOR).font('Helvetica-Bold').fontSize(11).text(value, x, y + 14, { width });
  }

  private drawFieldColumn(
    document: PdfDocumentInstance,
    x: number,
    y: number,
    width: number,
    fields: Array<{ label: string; value: string }>,
  ): void {
    let cursorY = y;
    fields.forEach((field) => {
      cursorY += this.drawField(document, x, cursorY, width, field.label, field.value) + 10;
    });
  }

  private drawField(
    document: PdfDocumentInstance,
    x: number,
    y: number,
    width: number,
    label: string,
    value: string,
  ): number {
    document.fillColor(LABEL_COLOR).font('Helvetica-Bold').fontSize(8).text(label.toUpperCase(), x, y, { width });
    const labelHeight = document.heightOfString(label, { width });
    const valueY = y + labelHeight + 3;
    document.fillColor(VALUE_COLOR).font('Helvetica').fontSize(10.2).text(value, x, valueY, { width, align: 'left' });
    const valueHeight = document.heightOfString(value, { width, align: 'left' });
    return labelHeight + 3 + valueHeight;
  }

  private measureOrderCardHeight(document: PdfDocumentInstance, order: IntakePdfOrder): number {
    const cardWidth = this.getContentWidth(document);
    const innerWidth = cardWidth - ORDER_CARD_ACCENT_WIDTH - ORDER_CARD_PADDING * 2;
    const titleHeight = this.measureTextHeight(document, 'Helvetica-Bold', 14, `Orden 1: ${order.code}`, innerWidth);
    const columnWidth = (innerWidth - COLUMN_GAP) / 2;

    const leftHeight = this.measureColumnHeight(document, columnWidth, [
      { label: 'Tipo de servicio', value: this.formatServiceType(order.serviceType) },
      { label: 'Equipo', value: order.equipmentLabel },
      { label: 'Técnico', value: order.technicianName?.trim() || 'Pendiente' },
    ]);
    const rightHeight = this.measureColumnHeight(document, columnWidth, [
      { label: 'Falla reportada', value: order.initialIssue },
      { label: 'Entrega estimada', value: this.formatOptionalDateTime(order.estimatedDeliveryDate) || 'No especificada' },
      { label: 'Notas', value: order.notes?.trim() || 'Sin notas' },
    ]);

    return ORDER_CARD_PADDING * 2 + titleHeight + 18 + Math.max(leftHeight, rightHeight);
  }

  private measureSingleOrderItemCardHeight(
    document: PdfDocumentInstance,
    item: GenerateSingleOrderSummaryPdfItem,
    index: number,
  ): number {
    void index;
    const contentWidth = this.getContentWidth(document) - 48;
    const issueHeight = this.measureTextHeight(document, 'Helvetica', 10, item.initialIssue || 'Sin detalle', contentWidth);
    const accessoryHeight = this.measureTextHeight(document, 'Helvetica', 8.2, `Accesorios: ${item.accessories?.trim() || 'Sin accesorios'}`, contentWidth / 2 - 8);
    const notesHeight = this.measureTextHeight(document, 'Helvetica', 8.2, `Observaciones: ${item.notes?.trim() || 'Sin observaciones'}`, contentWidth / 2);
    return Math.max(116, 94 + issueHeight + Math.max(accessoryHeight, notesHeight));
  }

  private measureFieldCardHeight(
    document: PdfDocumentInstance,
    fields: Array<{ label: string; value: string }>,
    title = 'Equipo',
  ): number {
    const cardWidth = this.getContentWidth(document);
    const innerWidth = cardWidth - ORDER_CARD_ACCENT_WIDTH - ORDER_CARD_PADDING * 2;
    const titleHeight = this.measureTextHeight(document, 'Helvetica-Bold', 14, title, innerWidth);
    const columnWidth = (innerWidth - COLUMN_GAP) / 2;
    const midpoint = Math.ceil(fields.length / 2);
    const leftHeight = this.measureColumnHeight(document, columnWidth, fields.slice(0, midpoint));
    const rightHeight = this.measureColumnHeight(document, columnWidth, fields.slice(midpoint));
    return ORDER_CARD_PADDING * 2 + titleHeight + 18 + Math.max(leftHeight, rightHeight);
  }

  private measureTextSectionHeight(document: PdfDocumentInstance, title: string, body: string): number {
    const cardWidth = this.getContentWidth(document) - ORDER_CARD_PADDING * 2;
    const titleHeight = this.measureTextHeight(document, 'Helvetica-Bold', 13, title, cardWidth);
    const bodyHeight = this.measureTextHeight(document, 'Helvetica', 10.5, body || 'Sin detalle', cardWidth);
    return ORDER_CARD_PADDING * 2 + titleHeight + 8 + bodyHeight + 12;
  }

  private measureTermsSectionHeight(document: PdfDocumentInstance): number {
    const innerWidth = this.getContentWidth(document);
    let total = this.measureTextHeight(document, 'Helvetica-Bold', 13, 'Términos y condiciones', innerWidth) + 8;

    STANDARD_TERMS.forEach((term) => {
      total += this.wrapTextToWidth(document, term.title, innerWidth, 'Helvetica-Bold', 10).length
        * document.font('Helvetica-Bold').fontSize(10).currentLineHeight();
      total += 3;
      total += this.wrapTextToWidth(document, term.body, innerWidth, 'Helvetica', 8.8).length
        * document.font('Helvetica').fontSize(8.8).currentLineHeight();
      total += 6;
    });

    return total;
  }

  private measureSummaryFieldHeight(
    document: PdfDocumentInstance,
    label: string,
    value: string,
    width: number,
  ): number {
    return this.measureTextHeight(document, 'Helvetica', 9, label, width)
      + 5
      + this.measureTextHeight(document, 'Helvetica-Bold', 11, value, width);
  }

  private wrapTextToWidth(
    document: PdfDocumentInstance,
    text: string,
    width: number,
    fontName: 'Helvetica' | 'Helvetica-Bold',
    fontSize: number,
  ): string[] {
    const normalized = String(text || '').replace(/\s+/g, ' ').trim();
    if (!normalized) {
      return [''];
    }

    document.font(fontName).fontSize(fontSize);
    const words = normalized.split(' ');
    const lines: string[] = [];
    let currentLine = '';

    words.forEach((word) => {
      const candidate = currentLine ? `${currentLine} ${word}` : word;
      if (!currentLine || document.widthOfString(candidate) <= width) {
        currentLine = candidate;
        return;
      }

      lines.push(currentLine);
      currentLine = word;
    });

    if (currentLine) {
      lines.push(currentLine);
    }

    return lines;
  }

  private measureColumnHeight(
    document: PdfDocumentInstance,
    width: number,
    fields: Array<{ label: string; value: string }>,
  ): number {
    return fields.reduce((total, field, index) => {
      const fieldHeight = this.measureTextHeight(document, 'Helvetica-Bold', 8, field.label.toUpperCase(), width)
        + 3
        + this.measureTextHeight(document, 'Helvetica', 10.2, field.value, width);
      return total + fieldHeight + (index < fields.length - 1 ? 10 : 0);
    }, 0);
  }

  private measureTextHeight(
    document: PdfDocumentInstance,
    fontName: 'Helvetica' | 'Helvetica-Bold',
    fontSize: number,
    text: string,
    width: number,
  ): number {
    return document.font(fontName).fontSize(fontSize).heightOfString(text, { width, align: 'left' });
  }

  private getContentWidth(document: PdfDocumentInstance): number {
    return document.page.width - PAGE_MARGIN * 2;
  }

  private getContentBottom(document: PdfDocumentInstance): number {
    return document.page.height - PAGE_MARGIN - FOOTER_HEIGHT - 8;
  }

  private formatDateTime(value: Date): string {
    return new Intl.DateTimeFormat('es-PE', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(value);
  }

  private formatOptionalDateTime(value?: string | Date | null): string | null {
    if (!value) {
      return null;
    }

    const date = value instanceof Date ? value : new Date(value);
    if (Number.isNaN(date.getTime())) {
      return null;
    }

    return this.formatDateTime(date);
  }

  private formatServiceType(value: string): string {
    switch (value) {
      case ServiceType.STANDARD_SERVICE:
        return 'Servicio estándar';
      case ServiceType.DIAGNOSIS:
        return 'Diagnóstico';
      case ServiceType.WARRANTY_SERVICE:
        return 'Servicio por garantía';
      case ServiceType.ASSEMBLY:
        return 'Ensamblaje';
      case ServiceType.CUSTOMER_SERVICE:
        return 'Atención al cliente';
      default:
        return value;
    }
  }

  private formatOperativeStatus(value: string): string {
    return SERVICE_ORDER_OPERATIVE_STATUS_LABELS[value] || value;
  }

  private formatEquipmentType(value: string): string {
    return EQUIPMENT_TYPE_LABELS[value] || value;
  }

  private formatPriority(value: string): string {
    const labels: Record<string, string> = { LOW: 'Baja', MEDIUM: 'Media', HIGH: 'Alta' };
    return labels[value] || value;
  }

  private resolveSingleOrderItems(input: GenerateSingleOrderSummaryPdfInput): GenerateSingleOrderSummaryPdfItem[] {
    if (input.items?.length) {
      return [...input.items].sort((left, right) => left.position - right.position || left.code.localeCompare(right.code));
    }
    return [
      {
        position: 1,
        code: input.code,
        priority: 'LOW',
        equipmentType: input.equipmentType ?? 'OTHER',
        brand: input.brand ?? null,
        model: input.model ?? null,
        serialNumber: input.serialNumber ?? null,
        accessories: input.accessories ?? null,
        notes: input.notes ?? null,
        initialIssue: input.initialIssue ?? 'Sin detalle',
      },
    ];
  }
}
